	.adv-print .amount-value { font-size: 20pt; font-weight: 700; margin-top: 6px; }
</style>

<div class="adv-print">
	<div class="header">
		{% if settings.office_logo %}
		<div class="header-logo">
			<img src="{{ settings.office_logo }}" alt="Logo">
		</div>
		{% endif %}
		<div class="header-info">
			<h1>{{ settings.razao_social or "Escritório de Advocacia" }}</h1>
			{% if settings.advogada %}
			<div class="muted">{{ settings.advogada }}{% if settings.oab %} — OAB {{ settings.oab }}{% endif %}</div>
			{% endif %}
		</div>
		<div class="header-meta">
			<div><strong>Acordo:</strong> {{ doc.name }}</div>
			<div><strong>Emissão:</strong> {{ frappe.utils.formatdate(frappe.utils.today()) }}</div>
		</div>
	</div>

	<div class="doc-title">
		<h1>Contrato de Honorários</h1>
		<div class="muted">{{ doc.title or doc.name }}</div>
	</div>

	<h2>Partes e Serviço</h2>
	<div class="grid">
		<div class="grid-row">
			<div class="grid-label">Cliente</div>
			<div class="grid-value">{{ client_name }}</div>
		</div>
		<div class="grid-row">
			<div class="grid-label">Serviço / Processo</div>
			<div class="grid-value">{{ case_title }}</div>
		</div>
		<div class="grid-row">
			<div class="grid-label">Status</div>
			<div class="grid-value">{{ doc.status or "—" }}</div>
		</div>
		<div class="grid-row">
			<div class="grid-label">Tipo de cobrança</div>
			<div class="grid-value">{{ doc.billing_type or "—" }}</div>
		</div>
	</div>

	<h2>Valores</h2>
	<div class="amount-box">
		<div class="muted">Valor total do acordo</div>
		<div class="amount-value">{{ frappe.utils.fmt_money(doc.valor_total_do_acordo or 0) }}</div>
	</div>
	<div class="grid">
		{% if doc.percentual_advogada %}
		<div class="grid-row">
			<div class="grid-label">Percentual advogada</div>
			<div class="grid-value">{{ doc.percentual_advogada }}%</div>
		</div>
		{% endif %}
		{% if doc.valor_advogada %}
		<div class="grid-row">
			<div class="grid-label">Valor advogada</div>
			<div class="grid-value">{{ frappe.utils.fmt_money(doc.valor_advogada) }}</div>
		</div>
		{% endif %}
		{% if doc.installment_count %}
		<div class="grid-row">
			<div class="grid-label">Parcelas</div>
			<div class="grid-value">{{ doc.installment_count }}</div>
		</div>
		{% endif %}
		{% if doc.valor_da_parcela %}
		<div class="grid-row">
			<div class="grid-label">Valor da parcela</div>
			<div class="grid-value">{{ frappe.utils.fmt_money(doc.valor_da_parcela) }}</div>
		</div>
		{% endif %}
	</div>

	{% if doc.remarks %}
	<h2>Observações</h2>
	<p>{{ doc.remarks }}</p>
	{% endif %}

	<p class="muted" style="margin-top: 32px;">Documento gerado pelo sistema Advocacia. Assinaturas conforme acordo firmado entre as partes.</p>
</div>
